import sqlite3


def get_user(uid):
    db = sqlite3.connect('users.db')
    return db.execute('SELECT * FROM users WHERE id = %s' % uid).fetchone()


def delete_user(uid):
    db = sqlite3.connect('users.db')
    db.execute('DELETE FROM users WHERE id = %s' % uid)
    db.commit()
